INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"284ef2d3-f520-58c1-b4b2-eac84af61e9e","title":"Business Studies · Grade 12 · Term 2: Leadership, quality and investments · Set A","subject":"Business Studies","grade":"Grade 12","questions":[{"question":"A manager consults team members before deciding. Which leadership style best fits?","options":["Democratic","Autocratic","Laissez-faire with no input","Coercive by definition"],"correct_index":0,"explanation":"Democratic leadership involves participation and consultation. It does not mean every decision must be unanimous.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"In the PDCA quality cycle, what follows Plan?","options":["Abandon","Do","Calculate tax","Recruit"],"correct_index":1,"explanation":"Plan–Do–Check–Act means test the plan, evaluate results and act on learning. Improvement should use evidence from the check stage.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why should an investor compare risk and return?","options":["High advertised returns remove all risk","All investments have identical risk","Higher potential returns may involve greater risk of loss","Past returns guarantee future returns"],"correct_index":2,"explanation":"Risk, expected return, liquidity and time horizon affect suitability. A high return claim alone is insufficient for a decision.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Which statement describes insurance pooling?","options":["Every premium is returned in full every month","Every loss is covered without exclusions","Insurers remove every possible business risk","Many policyholders' premiums help fund covered claims subject to policy terms"],"correct_index":3,"explanation":"Pooling spreads specified risks. Coverage, exclusions, excesses and other terms determine what a claim can pay.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"An investor is promised a guaranteed exceptionally high return with no risk and pressured to pay today. Which response is strongest?","options":["Pay immediately because a guarantee removes all risk.","Judge safety by the advert's expensive design alone.","Verify the provider, terms and risk independently before committing.","Borrow more because high returns cannot involve losses."],"correct_index":2,"explanation":"Unusually high guaranteed returns and pressure justify scrutiny. Compare credible information about risk, liquidity, fees and legitimacy; a promotional promise is not independent evidence of safety.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Leadership, quality and investments. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","bst"],"metadata":{"term":2,"focus":"Leadership, quality and investments","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=PIlgg85LNBo%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/bst-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"ddfd80af-fa49-55e5-bf63-bfe7d53417e5","title":"Business Studies · Grade 12 · Term 3: Human rights, responsibility and presentations · Set A","subject":"Business Studies","grade":"Grade 12","questions":[{"question":"A business installs an accessible entrance and adapts tasks for a qualified worker with a disability. Which principle is supported?","options":["Automatic exclusion","Inclusivity and reasonable accommodation","Price discrimination by definition","Avoidance of all quality standards"],"correct_index":1,"explanation":"Removing unnecessary barriers helps people participate fairly. Accommodation should respond to the worker's needs and job context.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"What does the triple bottom line consider?","options":["Only quarterly profit","Only the number of advertisements","People, planet and profit","Only staff uniforms"],"correct_index":2,"explanation":"A broader assessment considers social, environmental and economic performance. Financial results alone do not show all effects of business activity.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Which example most clearly represents a CSI project?","options":["Recording daily sales","Pricing stock for a normal sale","Calculating a routine payslip","Funding and equipping a community learning centre"],"correct_index":3,"explanation":"Corporate social investment involves resources committed to community-development initiatives. Evaluate outcomes and sustainability, not just spending.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why state the source and date of a chart in a presentation?","options":["So the audience can judge relevance and verify the evidence","To make every old figure current","To avoid explaining the chart","To guarantee the chart is unbiased"],"correct_index":0,"explanation":"Source and date help the audience assess credibility and currency. The presenter must still explain methods, units and limitations.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A firm funds a community centre but ignores complaints about unsafe waste disposal. Which assessment fits the triple bottom line?","options":["Any donation proves full sustainability.","Only the size of the donation matters.","The CSI project does not remove the need to address environmental and social harms.","Community benefits automatically cancel every environmental cost."],"correct_index":2,"explanation":"People, planet and profit must all be considered. Assess the centre's benefit alongside the firm's operating impacts and require evidence of corrective environmental action.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Human rights, responsibility and presentations. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","bst"],"metadata":{"term":3,"focus":"Human rights, responsibility and presentations","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=PIlgg85LNBo%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/bst-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"003d4d83-3675-56df-939d-16edc353f446","title":"Business Studies · Grade 12 · Term 4: Integrated business decision revision · Set A","subject":"Business Studies","grade":"Grade 12","questions":[{"question":"A new law raises compliance costs for all firms. Which environment is the main source of this change?","options":["Micro environment only","The internal staff cafeteria","Macro environment","A single customer's preferences"],"correct_index":2,"explanation":"Legislation is part of the wider macro environment. Businesses may influence policy collectively but cannot directly control it.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A SWOT analysis identifies a firm's strong customer service. Which category is it?","options":["Threat","Opportunity","External weakness","Strength"],"correct_index":3,"explanation":"A strength is an internal advantage. Opportunities and threats arise mainly outside the business.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why can limited liability matter when choosing a company form?","options":["Shareholders' exposure is generally limited, subject to legal exceptions","It guarantees company debts never exist","It prevents every director from any liability","It means no records are needed"],"correct_index":0,"explanation":"Limited liability generally separates company obligations from shareholders, but legal exceptions and directors' duties still matter.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A quality programme raises costs but reduces returns and customer complaints. What should management evaluate?","options":["Only the initial cost","Total costs and benefits using evidence over time","Only the colour of the quality poster","Assume fewer complaints prove every product is perfect"],"correct_index":1,"explanation":"Evaluate prevention, inspection, defect costs and customer outcomes together. A single metric does not establish the overall effect.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A SWOT lists a new competitor as a weakness and poor staff training as a threat. Which correction is justified?","options":["Both belong under strengths because they can be improved.","Both are opportunities because every change is beneficial.","The competitor is an external threat; inadequate training is an internal weakness.","Training is always external and competition always internal."],"correct_index":2,"explanation":"SWOT distinguishes internal capabilities from external conditions. A competing firm is external, while the business's own staff-development gap is internal; the distinction guides suitable responses.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Integrated business decision revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","bst"],"metadata":{"term":4,"focus":"Integrated business decision revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=PIlgg85LNBo%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/bst-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"4d635807-be7c-5ee0-9ace-e4f6e0939ed2","title":"Economics · Grade 12 · Term 2: Market structures, failure and trade · Set A","subject":"Economics","grade":"Grade 12","questions":[{"question":"In perfect competition, an individual firm is generally a…","options":["Sole market supplier","Price taker","Legal monopoly by definition","Setter of the market price independently"],"correct_index":1,"explanation":"A small firm sells an identical product in a market with many buyers and sellers, so it takes the market price in the model.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"What distinguishes an oligopoly?","options":["One buyer and no sellers","Unlimited identical firms with no influence","A small number of interdependent large firms","No barriers to entry in every case"],"correct_index":2,"explanation":"With a few significant firms, each firm's actions affect rivals' choices. Strategic interdependence is a key feature.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why may public goods be underprovided by private markets?","options":["They are always rival in consumption","They must be free to produce","No one receives any benefit from them","Non-excludability can create a free-rider problem"],"correct_index":3,"explanation":"If people cannot easily be excluded from benefits, collecting payment is difficult. This can weaken private incentives to supply the socially desirable quantity.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"What is a tariff?","options":["A tax on imported goods","A quota on how many workers can apply","A ban on all domestic production","A guaranteed subsidy to every consumer"],"correct_index":0,"explanation":"Import tariffs raise the cost of imported goods and can protect domestic producers, but may raise consumer costs and invite retaliation.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A town relies on one water supplier with high fixed infrastructure costs. Why is counting firms alone insufficient to recommend breaking it into many suppliers?","options":["More firms always guarantee lower total infrastructure costs.","A monopoly can never require regulation.","Cost structure, economies of scale, service access and regulation also affect the best arrangement.","Water has no infrastructure costs."],"correct_index":2,"explanation":"Market structure must be considered alongside costs and public-interest outcomes. Duplicating networks may be costly, while regulation and accountability can address price, access and quality concerns.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Market structures, failure and trade. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","eco"],"metadata":{"term":2,"focus":"Market structures, failure and trade","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=dq9Dq46iLKo%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lv-97xKN0eM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/eco-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"aa8b3e4b-2307-5618-abad-8c2c48f2c5c6","title":"Economics · Grade 12 · Term 3: Inflation, indicators and sustainable tourism · Set A","subject":"Economics","grade":"Grade 12","questions":[{"question":"A price index rises from 120 to 126. Find the inflation rate for the period.","options":["6%","4.76%","5%","126%"],"correct_index":2,"explanation":"Inflation = (126−120)/120×100=5%. The six index points are not six percent of the original index.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"What can cause demand-pull inflation?","options":["A fall in every source of demand","A guaranteed fall in the money supply alone","All productive resources become free","Aggregate demand grows faster than available real output at capacity"],"correct_index":3,"explanation":"Pressure from total spending can bid up prices when real output cannot expand sufficiently. Distinguish this from cost-push pressures.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why is tourism described as having a multiplier effect?","options":["Tourist spending generates further income and spending in connected activities","Every rand automatically doubles exactly once","All spending stays inside one hotel","Imports do not affect any tourism income"],"correct_index":0,"explanation":"Initial spending supports incomes, some of which are spent again. Saving, taxes and imports are leakages that affect the size of the effect.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which indicator combines health, education and income dimensions?","options":["Consumer Price Index only","Human Development Index","Exchange rate only","Prime lending rate"],"correct_index":1,"explanation":"HDI combines life expectancy, education and income measures. It complements economic output indicators rather than measuring every aspect of well-being.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"The inflation rate falls from 8% to 5%, remaining positive. A learner says average prices have fallen. Which correction is right?","options":["Prices must fall by 3% because the rate fell by three points.","All goods now have unchanged prices.","Prices are rising more slowly; a lower positive inflation rate is not a fall in the price level.","Inflation measures only employment."],"correct_index":2,"explanation":"Inflation is the rate of increase of the general price level. A fall in that positive rate is disinflation, while a falling general price level would require negative inflation.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Inflation, indicators and sustainable tourism. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","eco"],"metadata":{"term":3,"focus":"Inflation, indicators and sustainable tourism","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=dq9Dq46iLKo%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lv-97xKN0eM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/eco-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"54507b45-cce5-5ba1-882c-d89a4a528dc4","title":"Economics · Grade 12 · Term 4: Integrated macro- and microeconomics revision · Set A","subject":"Economics","grade":"Grade 12","questions":[{"question":"In a simplified closed economy without government, MPC = 0.8. Find the expenditure multiplier.","options":["0.2","1.25","8","5"],"correct_index":3,"explanation":"k=1/(1−MPC)=1/0.2=5 under the stated assumptions. A more complex economy has additional leakages.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why does real GDP per capita provide more context than total real GDP alone?","options":["It relates real output to population size","It measures every household's exact income","It removes all inequality automatically","It excludes population from analysis"],"correct_index":0,"explanation":"Divide real GDP by population. An average helps comparison but does not show how income is distributed.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"If the rand depreciates against the dollar, what happens to the rand price of a fixed dollar import price, all else equal?","options":["It falls","It rises","It necessarily stays equal","It becomes zero"],"correct_index":1,"explanation":"A weaker rand means more rand are needed for each dollar. Actual prices may also depend on contracts, taxes and other costs.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which policy response most directly addresses a negative production externality in the textbook model?","options":["Ignoring the pollution cost entirely","Paying firms more for extra pollution without conditions","A well-designed pollution charge linked to external costs","Removing all environmental information"],"correct_index":2,"explanation":"A charge can internalise external costs and influence production choices. Design, enforcement and distributional effects determine real-world results.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"In a simplified multiplier model MPC=0.8 gives k=5. Why should a R1 million injection not be treated as a guaranteed R5 million real-output increase in practice?","options":["The model proves unlimited resources exist.","A multiplier of five means every household receives R5 million.","Leakages, capacity limits, imports and behavioural responses can change the outcome.","Government spending can never affect demand."],"correct_index":2,"explanation":"The simple model rests on restrictive assumptions. Real economies have taxes, imports, saving changes and capacity constraints, so its predicted total effect needs contextual qualification.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Integrated macro- and microeconomics revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","eco"],"metadata":{"term":4,"focus":"Integrated macro- and microeconomics revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=dq9Dq46iLKo%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lv-97xKN0eM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/eco-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"bc821f6f-b871-5dab-b999-6f644174a0ab","title":"Geography · Grade 12 · Term 2: Fluvial processes and settlements · Set A","subject":"Geography","grade":"Grade 12","questions":[{"question":"What is river rejuvenation?","options":["A river ceasing every process permanently","The automatic creation of a lake at every mouth","Renewed erosive energy, often following a fall in base level or land uplift","A river becoming older by one year"],"correct_index":2,"explanation":"A change in relative base level or gradient can renew vertical erosion. Features can include incised meanders or knickpoints.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"What is rural–urban migration?","options":["Only movement between two farms","Every daily trip to a shop","The movement of river sediment","Movement of people from rural areas to towns and cities"],"correct_index":3,"explanation":"Rural–urban migration changes residence and can affect both origin and destination. Do not confuse it with daily commuting.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Which factor commonly helps explain a settlement's original site?","options":["Access to water and a suitable location for activities","Only its modern postal code","A guarantee of future industrial growth","Its current population ranking alone"],"correct_index":0,"explanation":"A site is the physical location and its characteristics. Situation concerns its relative location and connections to other places.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Why may informal settlements develop rapidly near cities?","options":["Every resident prefers poor services","Affordable formal housing may not keep pace with migration and household formation","Urban housing demand is always zero","They occur only where no jobs exist"],"correct_index":1,"explanation":"Housing supply, land access, incomes and population change interact. Avoid explanations that blame residents or assume one universal cause.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"A city relocates informal households far from jobs without reliable transport. Which evaluation considers settlement needs most fully?","options":["New buildings alone guarantee improved access to livelihoods.","Distance never affects household costs.","Assess housing quality together with affordability, livelihoods, transport and community participation.","Exclude residents because only building counts matter."],"correct_index":2,"explanation":"Settlement policy affects daily access and costs as well as structures. A stronger appraisal includes residents' priorities and the feasibility of reaching work, schools and services.","cognitive_level":{"code":"L3","label":"Analysing and evaluating","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Fluvial processes and settlements. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","geo"],"metadata":{"term":2,"focus":"Fluvial processes and settlements","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=PbIoAvtDReA%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20GEOGRAPHY%20_%20GR%2010-12%20_%20WEB_C9A9.pdf?ver=2015-01-27-154144-177","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/geo-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and remembering","Understanding and applying","Analysing and evaluating"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"72bdd431-781f-586c-8bd4-445301aae7c7","title":"Geography · Grade 12 · Term 3: South Africa's economic geography · Set A","subject":"Geography","grade":"Grade 12","questions":[{"question":"Which activity belongs to the primary sector?","options":["Manufacturing steel","Banking","Retailing clothes","Mining iron ore"],"correct_index":3,"explanation":"The primary sector extracts or produces raw materials. Steelmaking transforms them in the secondary sector.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Why can transport infrastructure influence industrial location?","options":["It affects access to inputs, markets and distribution costs","Factories never need inputs","All transport costs are identical everywhere","It removes the need for labour"],"correct_index":0,"explanation":"Transport is one location factor alongside labour, power, water, land and policy. Different industries weigh these differently.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"Which best describes small-scale subsistence farming?","options":["Only production for global export chains","Production mainly for the household's own use","Mining on agricultural land","A guarantee of no surplus in any year"],"correct_index":1,"explanation":"Subsistence farming primarily meets household needs; some surplus may be sold. Scale and production purpose are related but distinct.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Why do mining benefits need to be assessed alongside costs?","options":["Mining creates no costs","All communities receive identical benefits","Jobs and export earnings can coexist with environmental and social impacts","Only export value matters"],"correct_index":2,"explanation":"Evaluate employment, revenue, land, water, health, rehabilitation and distribution. A balanced assessment uses evidence from affected areas.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"A proposed mine promises jobs but threatens a river used by downstream farms. Which evidence is needed for a balanced decision?","options":["Only the promoter's projected job number.","Only a promotional photograph of machinery.","Credible employment estimates and environmental, water-use and community-impact assessments.","An assumption that economic benefits erase all environmental costs."],"correct_index":2,"explanation":"Economic geography weighs benefits and costs across places and groups. Investigate water impacts, mitigation and who gains or bears risks alongside employment and revenue.","cognitive_level":{"code":"L3","label":"Analysing and evaluating","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: South Africa's economic geography. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","geo"],"metadata":{"term":3,"focus":"South Africa's economic geography","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=PbIoAvtDReA%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20GEOGRAPHY%20_%20GR%2010-12%20_%20WEB_C9A9.pdf?ver=2015-01-27-154144-177","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/geo-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and remembering","Understanding and applying","Analysing and evaluating"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"b891f6fe-414e-53dc-936f-14a77c04d455","title":"Geography · Grade 12 · Term 4: Climate, drainage and map-skill revision · Set A","subject":"Geography","grade":"Grade 12","questions":[{"question":"On a 1:50 000 map, two points are 4 cm apart. Find straight-line ground distance.","options":["2 km","20 km","0.2 km","200 km"],"correct_index":0,"explanation":"4×50 000 = 200 000 cm = 2 km. A route distance may be longer than the straight-line distance.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"What does a drainage basin include?","options":["Only the river mouth","The area drained by a river and its tributaries","Only the deepest channel point","Every ocean connected to any river"],"correct_index":1,"explanation":"Watershed boundaries separate drainage basins. Water within a basin generally drains towards its river system.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"What often happens where warm, moist air rises up a mountain slope?","options":["It always heats without limit","Water vapour instantly becomes rock","It cools, may condense and can produce orographic rain","Every cloud evaporates regardless of conditions"],"correct_index":2,"explanation":"Rising air expands and cools. If it reaches saturation, condensation can form cloud and precipitation on the windward slope.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Why interpret a map together with its key and scale?","options":["All maps use identical symbols and scales","The key replaces all spatial thinking","Scale is only decoration","Symbols and distances need their stated meanings and units"],"correct_index":3,"explanation":"A key explains symbols and a scale links map distance to ground distance. Read both before identifying features or measuring.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"Two points are 2 km apart in a straight line on a map. A learner says the walking route must take 20 minutes at 6 km/h. Why is this uncertain?","options":["Map scale guarantees every route is flat.","Walking speed cannot be related to distance.","The path may be longer or steeper than the straight-line distance.","Straight-line distance always includes detours."],"correct_index":2,"explanation":"The 20-minute calculation assumes a 2 km route at constant 6 km/h. Actual paths, contours, obstacles and stops may change distance and speed; use route and relief information.","cognitive_level":{"code":"L3","label":"Analysing and evaluating","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Climate, drainage and map-skill revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","geo"],"metadata":{"term":4,"focus":"Climate, drainage and map-skill revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=PbIoAvtDReA%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20GEOGRAPHY%20_%20GR%2010-12%20_%20WEB_C9A9.pdf?ver=2015-01-27-154144-177","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/geo-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and remembering","Understanding and applying","Analysing and evaluating"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"4ebc42c1-70d6-533f-9e2c-366cf9675036","title":"History · Grade 12 · Term 2: Black Consciousness, transition and reconciliation · Set A","subject":"History","grade":"Grade 12","questions":[{"question":"What was a central emphasis of Black Consciousness associated with Steve Biko?","options":["Acceptance of apartheid's racial hierarchy","Withdrawal of all criticism of oppression","A claim that only legislation affects identity","Psychological liberation, dignity and self-reliance among oppressed black people"],"correct_index":3,"explanation":"Black Consciousness challenged internalised oppression and promoted agency and solidarity. Explain its context and influence using specific evidence.","cognitive_level":{"code":"L1","label":"Historical knowledge and evidence retrieval","band":"lower"}},{"question":"What was one purpose of the Truth and Reconciliation Commission?","options":["Investigate gross human-rights violations and create a public record of testimony","Guarantee that no disagreements about the past remained","Provide automatic amnesty without conditions","Replace all historical research permanently"],"correct_index":0,"explanation":"The TRC sought truth-telling and reconciliation through its mandate. Amnesty required specified conditions; its outcomes and limits remain subjects of evaluation.","cognitive_level":{"code":"L1","label":"Historical knowledge and evidence retrieval","band":"lower"}},{"question":"How did the end of the Cold War affect South Africa's political context?","options":["It alone mechanically caused every decision","It changed international pressures and strategic calculations around negotiations","It had no international significance","It removed every domestic conflict immediately"],"correct_index":1,"explanation":"Global changes interacted with internal resistance, economic pressures and leadership decisions. Avoid treating international change as the sole cause.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"Why evaluate both achievements and limitations of reconciliation initiatives?","options":["Stated aims automatically prove success","Critical evaluation is incompatible with evidence","Their aims and actual effects may differ across people and issues","All testimony gives the same experience"],"correct_index":2,"explanation":"A balanced argument compares goals, processes and outcomes, including justice, acknowledgement and unresolved material inequalities.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"A learner argues that public TRC testimony proves reconciliation was fully achieved for everyone. Which response is most defensible?","options":["Assume testimony guarantees all victims received the same outcome.","Reject every testimony because reconciliation is difficult.","Distinguish the creation of a public record from the varied experiences and unresolved limits of reconciliation.","Use the commission's name as sufficient proof of complete success."],"correct_index":2,"explanation":"An institution's aims and public proceedings are not identical to all social outcomes. Evaluate achievements and limitations with evidence from affected people and the broader context.","cognitive_level":{"code":"L3","label":"Evaluate evidence and perspectives","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Black Consciousness, transition and reconciliation. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","hist"],"metadata":{"term":2,"focus":"Black Consciousness, transition and reconciliation","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=luMlDutfFbc%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20%20HISTORY%20GR%2010-12%20%20WeB.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/hist-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS-informed historical knowledge and source skills","cognitive_levels":["Historical knowledge and evidence retrieval","Concepts and straightforward interpretation","Evaluate evidence and perspectives"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"8903a47b-7548-54f8-b179-072f3d165aef","title":"History · Grade 12 · Term 3: Globalisation and a new world order · Set A","subject":"History","grade":"Grade 12","questions":[{"question":"What does globalisation describe?","options":["Increasing cross-border connections in economies, politics, culture and communication","The end of all international interaction","Only migration between two villages","A single country's weather pattern"],"correct_index":0,"explanation":"Globalisation has several dimensions and uneven effects. Define the dimension relevant to the question before evaluating its consequences.","cognitive_level":{"code":"L1","label":"Historical knowledge and evidence retrieval","band":"lower"}},{"question":"Why can globalisation affect African states differently?","options":["Every state has identical resources and institutions","Economic structures, bargaining power and domestic policies vary","Geography and history have no influence","All foreign investment has identical effects"],"correct_index":1,"explanation":"Different positions in trade, finance and production shape opportunities and constraints. Support comparisons with specific evidence.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"An editorial praises an international financial policy. What should a historian investigate?","options":["Only the font size","Whether praise proves neutrality","Who produced it, its interests, evidence and intended audience","Whether the headline rhymes"],"correct_index":2,"explanation":"Editorials provide perspectives and arguments. Assess evidence and context, and compare with other affected groups' experiences.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"What makes an argument about a new world order convincing?","options":["Only a slogan","A list of dates with no relationship to the question","Ignoring evidence from outside one country","A supported claim that weighs change, continuity and competing interpretations"],"correct_index":3,"explanation":"A strong argument links evidence across cases to a clear judgment, while acknowledging limits and alternative interpretations.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"An editorial welcomes a global financial policy while workers' accounts describe job losses. Which synthesis is strongest?","options":["Only the editorial counts because it is published.","Only negative effects can ever be historical evidence.","Evaluate the policy's different effects on groups using contextual evidence and each source's perspective.","Opposing accounts prove neither group experienced any effect."],"correct_index":2,"explanation":"Globalisation can distribute gains and adjustment costs unevenly. Assess specific claims, interests and context to form a qualified argument rather than presume one uniform outcome.","cognitive_level":{"code":"L3","label":"Evaluate evidence and perspectives","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Globalisation and a new world order. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","hist"],"metadata":{"term":3,"focus":"Globalisation and a new world order","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=luMlDutfFbc%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20%20HISTORY%20GR%2010-12%20%20WeB.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/hist-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS-informed historical knowledge and source skills","cognitive_levels":["Historical knowledge and evidence retrieval","Concepts and straightforward interpretation","Evaluate evidence and perspectives"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"96602f18-81ed-572e-b77d-e6a34c3dba11","title":"History · Grade 12 · Term 4: Source-based and essay examination revision · Set A","subject":"History","grade":"Grade 12","questions":[{"question":"A question says use the source and your own knowledge. What is required?","options":["Copy only the source","Integrate source evidence with relevant contextual knowledge","Ignore the source completely","Write unrelated facts from any topic"],"correct_index":1,"explanation":"Show what the source establishes and connect it to accurate outside knowledge. Keep both relevant to the wording of the question.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"What is the best way to introduce a historical essay?","options":["Repeat every fact you remember","Avoid taking any position","State a clear position responding to the question and outline its line of argument","Copy the question without adding meaning"],"correct_index":2,"explanation":"The introduction should frame the argument. The body supports it with evidence and the conclusion returns to the judgment.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"How should a learner use a political cartoon as evidence?","options":["Treat every drawing as a literal photograph","Assume humour means it has no historical use","Ignore captions and dates","Interpret symbols and message in relation to creator, audience and historical context"],"correct_index":3,"explanation":"Cartoons compress and exaggerate viewpoints. Context and visual details help explain the message and its limitations as evidence.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"Why is chronology important in explaining historical causation?","options":["A proposed cause must precede the effect and fit the wider sequence","Every earlier event caused every later event","Dates alone replace explanation","Events after an outcome always caused it"],"correct_index":0,"explanation":"Chronology helps test causal claims, but an earlier event is not automatically a cause. Explain mechanisms and supporting evidence.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"An essay uses an event in 1965 as the cause of a policy adopted in 1960. What revision is needed?","options":["Keep the claim because all related events are interchangeable.","Remove every date from the essay.","Correct the chronology and identify earlier causes; the later event may be a consequence or later development.","Treat the later event as earlier without evidence."],"correct_index":2,"explanation":"A cause must precede its effect. Establish an accurate sequence and distinguish origins, consequences and later reinforcement before building a causal argument.","cognitive_level":{"code":"L3","label":"Evaluate evidence and perspectives","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Source-based and essay examination revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","hist"],"metadata":{"term":4,"focus":"Source-based and essay examination revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=luMlDutfFbc%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20%20HISTORY%20GR%2010-12%20%20WeB.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/hist-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS-informed historical knowledge and source skills","cognitive_levels":["Historical knowledge and evidence retrieval","Concepts and straightforward interpretation","Evaluate evidence and perspectives"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"17d67195-6466-521f-8d09-4f69dec3af52","title":"Tourism · Grade 12 · Term 2: World time zones, icons and currency · Set A","subject":"Tourism","grade":"Grade 12","questions":[{"question":"Cape Town is UTC+2 and London is UTC+0 for this question. When it is 14:00 in Cape Town, what time is it in London?","options":["12:00","16:00","14:00","10:00"],"correct_index":0,"explanation":"Subtract the two-hour difference when moving from UTC+2 to UTC+0. Use the offsets provided; daylight-saving rules can differ by date.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A flight leaves Johannesburg at 20:00 (UTC+2), lasts 8 hours and lands in a city at UTC+0. Find local arrival time.","options":["04:00 next day","02:00 next day","06:00 next day","22:00 same day"],"correct_index":1,"explanation":"Departure is 18:00 UTC. Add 8 hours to get 02:00 UTC the next day, which is also destination local time.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why is the Eiffel Tower called a tourism icon?","options":["It is the only attraction in France","Every icon must be a natural feature","It is widely recognised and associated with its destination","An icon has no marketing value"],"correct_index":2,"explanation":"An icon is a recognisable symbol or attraction associated with a place. Its reputation can support destination awareness, though visitors have varied interests.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A tourist buys €200 at R21 per euro, ignoring fees. What is the rand cost?","options":["R9.52","R221","R3 800","R4 200"],"correct_index":3,"explanation":"Multiply foreign currency by rand per unit: 200×21=R4 200. Check the appropriate rate and fees for a real transaction.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A flight leaves Johannesburg at 23:00 UTC+2, lasts 9 hours and arrives in a city at UTC−5. Which local arrival is correct, using only these offsets?","options":["08:00 next day","15:00 same day","01:00 next day","06:00 next day"],"correct_index":2,"explanation":"Departure is 21:00 UTC. Nine hours later is 06:00 UTC the next day; subtract five hours for the destination to obtain 01:00. Track both offset and date.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: World time zones, icons and currency. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","tour"],"metadata":{"term":2,"focus":"World time zones, icons and currency","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=vPhsHBIjpnI%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QCDkiagAGeI%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/tour-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"25c147ab-89e2-5aab-aaf2-a1ce8bbb9664","title":"Tourism · Grade 12 · Term 3: Responsible tourism, heritage and service · Set A","subject":"Tourism","grade":"Grade 12","questions":[{"question":"A hotel offers local jobs but pollutes the river. How should its sustainability be assessed?","options":["Jobs prove it is sustainable in every respect","Consider the economic benefit alongside environmental and social harms","Pollution is irrelevant to tourism","Only the hotel's advertising matters"],"correct_index":1,"explanation":"The three pillars must be considered together. Economic benefits do not cancel environmental damage without addressing it.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why consult communities when managing a heritage site?","options":["Heritage exists only for visitors","Community views can never change","Their knowledge, rights and interests are central to responsible management","Consultation guarantees agreement on every issue"],"correct_index":2,"explanation":"Participation improves legitimacy and interpretation. Manage differing interests transparently rather than assuming tourism overrides local needs.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which method provides structured customer feedback?","options":["Only counting advertising posters","Ignoring complaints","Assuming silence means perfect service","A clear post-visit survey with relevant questions"],"correct_index":3,"explanation":"A survey can collect comparable feedback. Include different guests, consider response bias and use findings to make improvements.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why should a tourism employee understand their employment contract?","options":["It sets out duties, terms and relevant employment conditions","It replaces every applicable labour law","It guarantees no workplace disagreement","It removes all responsibilities from both parties"],"correct_index":0,"explanation":"A contract helps clarify expectations. Its terms must be considered within the applicable legal framework and should be understood before agreement.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A hotel reports 95% satisfaction from a survey offered only to repeat guests. Which evaluation is sound?","options":["It proves 95% of every possible guest is satisfied.","Repeat guests always provide unbiased national tourism data.","The result describes respondents but may not represent first-time or dissatisfied guests.","Surveys cannot provide any useful service evidence."],"correct_index":2,"explanation":"The sampling method can exclude dissatisfied guests who never return. Include a broader guest sample and examine response rates before generalising the result.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Responsible tourism, heritage and service. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","tour"],"metadata":{"term":3,"focus":"Responsible tourism, heritage and service","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=vPhsHBIjpnI%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QCDkiagAGeI%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/tour-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"ec192aac-dc92-57a0-8212-d6bddd7c8a4e","title":"Tourism · Grade 12 · Term 4: Integrated travel and destination revision · Set A","subject":"Tourism","grade":"Grade 12","questions":[{"question":"A city is UTC−5 and Johannesburg UTC+2. When it is 18:00 in Johannesburg, what time is it in the other city using these offsets?","options":["01:00 next day","13:00 same day","11:00 same day","23:00 same day"],"correct_index":2,"explanation":"The offset difference is seven hours. Johannesburg is ahead, so subtract seven hours: 18:00−7=11:00.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A tour costs R1 500 before a 10% discount. Find the discounted price.","options":["R150","R1 650","R1 490","R1 350"],"correct_index":3,"explanation":"Discount = 1 500×0.10=R150. Subtract it to get R1 350. The discount amount is not the final price.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A guide learns that an attraction is temporarily closed. What is the best response?","options":["Verify details, inform travellers and offer a suitable revised itinerary","Keep selling the unchanged itinerary without disclosure","Invent a reason that cannot be checked","Leave travellers stranded at the gate"],"correct_index":0,"explanation":"Good service uses accurate current information and practical alternatives. Explain material changes clearly before the visit where possible.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"What makes a destination-marketing claim credible?","options":["Unverified awards and invented visitor counts","Specific accurate claims supported by current evidence","A promise that every visitor will have identical experiences","Replacing information with slogans only"],"correct_index":1,"explanation":"Evidence, current details and honest scope support informed choices. Marketing should match the experience and resources actually available.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A tour costing R1 500 offers 10% off, then charges a R200 booking fee. A competitor offers R1 450 all-inclusive for identical services. Which stated total is lower?","options":["The discounted tour's R1 350 because fees do not count.","Both cost R1 450.","The competitor's R1 450; the discounted tour totals R1 550.","The first tour costs R1 200 after adding the fee."],"correct_index":2,"explanation":"Discounted base price is 1 500×0.9=R1 350; adding R200 gives R1 550. Compare complete prices and equivalent services rather than the headline discount alone.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Integrated travel and destination revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","tour"],"metadata":{"term":4,"focus":"Integrated travel and destination revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=vPhsHBIjpnI%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QCDkiagAGeI%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/tour-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}}]$smartbridge$::jsonb)
